UPDATE relations.sys_email_send_limit
SET send_date = #{sendDate}, send_count = #{sendCount}, last_sent_at = #{lastSentAt}
WHERE scope_key = #{scopeKey}

UPDATE relations.sys_email_code
SET code_hash = #{codeHash}, expires_at = #{expiresAt}, failed_attempts = 0, used = FALSE
WHERE email = #{email}

UPDATE relations.sys_email_code
SET failed_attempts = failed_attempts + 1
WHERE email = #{email}

UPDATE relations.sys_email_code
SET used = TRUE
WHERE email = #{email}
